mapper.update:
update exam_question_result
set correct_count = #{correctCount},
    score_per_question = #{scorePerQuestion},
    section_type = #{sectionType},
    raw_score = #{rawScore}
where exam_id = #{examId}
  and question_code = #{questionCode}

mapper.select:
select *
from exam_question_result
where exam_id = #{examId}
  and question_code = #{questionCode}
